package org.firstinspires.ftc.teamcode.autos;

import org.firstinspires.ftc.teamcode.Actions;
import org.firstinspires.ftc.teamcode.Robot;
import com.crossbotics.ftchelper.robot.Auto;
import com.crossbotics.ftchelper.robot.Steps;
import com.qualcomm.robotcore.eventloop.opmode.Autonomous;

// preselectTeleOp: your TeleOp's name, exactly as in @TeleOp(name = ...) in Controls.java
@Autonomous(name = "Score and Park", group = "Autos", preselectTeleOp = "Quick Start TeleOp")
public class ScoreAndPark extends Auto<Robot> {

    @Override
    protected boolean mirrorForRed() {
        return false;   // BIOBUZZ's field is turned half a turn between the alliances
    }

    @Override
    protected void steps(Steps s, Robot robot) {
        s.start("Our wall, left corner tile, facing the field", -56, -61.1, 0)
         .run("Hold the piece", robot.claw::close)
         .move("To the goal", 24, 0, 0.6)
         .action(Actions.scoreHigh(robot), 5)
         .parkWithSeconds(3)
         .move("Park", 20, 90, 0.7);
    }
}

package com.crossbotics.ftchelper.examples.gobildabot.autos;

import com.crossbotics.ftchelper.examples.gobildabot.Actions;
import com.crossbotics.ftchelper.examples.gobildabot.Robot;
import com.crossbotics.ftchelper.robot.Auto;
import com.crossbotics.ftchelper.robot.Steps;
import com.qualcomm.robotcore.eventloop.opmode.Autonomous;

// preselectTeleOp: your TeleOp's name, exactly as in @TeleOp(name = ...) in Controls.java
@Autonomous(name = "Built Starter Auto", group = "Examples", preselectTeleOp = "goBILDA Bot TeleOp")
public class BuiltStarterAuto extends Auto<Robot> {

    @Override
    protected boolean mirrorForRed() {
        return false;   // BIOBUZZ's field is turned half a turn between the alliances
    }

    @Override
    protected void steps(Steps s, Robot robot) {
        s.start("Our wall, left corner tile, facing the field", -56, -62.95, 0)
         .run("Spin up", robot.launcher::spinUp)
         .move("Out from the wall", 20, 0, 0.6)
         .waitSeconds("Settle", 0.3)
         .turn("Face the HIVE", -45, 0.5)
         .action(Actions.fireAll(robot), 8)
         .parkWithSeconds(4)
         .turnTo("Square up", 0, 0.5)
         .move("Leave", 12, 0, 0.7);
    }
}

package com.team8938.autos;

import com.team8938.Actions;
import com.team8938.Robot;
import com.crossbotics.ftchelper.robot.Auto;
import com.crossbotics.ftchelper.robot.Steps;
import com.qualcomm.robotcore.eventloop.opmode.Autonomous;

// preselectTeleOp: your TeleOp's name, exactly as in @TeleOp(name = ...) in Controls.java
@Autonomous(name = "2 piece", group = "Test", preselectTeleOp = "Main TeleOp")
public class TwoPiece extends Auto<Robot> {

    @Override
    protected void steps(Steps s, Robot robot) {
        s.start("NEAR: \"left\" tile", 90)
         .alongside(Actions.fireAll(robot))
         .move("Strafe out", 12.5, 45, 1)
         .turnTo("Face \"in\"", -30, 0.4)
         .waitSeconds("Wait", 2.25)
         .run("Lift", () -> robot.lift.goTo("high"))
         .move("Back", -8, 0, 0.5);
    }
}

