import com.crossbotics.ftchelper.pedro.PedroPath;
import com.crossbotics.ftchelper.robot.PathAt;

// With your other fields, at the top of the class:
static final PedroPath TO_GOAL = PedroPath.line(-56, -61,  -48, -50).keepHeading(0)
        .then(PedroPath.curve(-48, -50,  -44, -36,  -30, -30).turnTo(0, 45))
        .holdEnd();

// In steps(Steps s, Robot robot):
s.start("Against our wall, in the left corner tile, facing the field", -56, -61, 0)
 .follow("To the goal", TO_GOAL,
         PathAt.fraction(0.5, "Intake on", robot.intake::in));

// With the other imports, at the top of the file:
import com.crossbotics.ftchelper.pedro.PedroPath;
import com.crossbotics.ftchelper.robot.PathAt;

// With your other fields, at the top of the class:
static final PedroPath AROUND = PedroPath.curve(40, -61,  50, -40,  20, -40,  30, -20).facePathBackwards().maxSpeed(0.5)
        .then(PedroPath.line(30, -20,  10, -40).facePoint(0, -20))
        .then(PedroPath.line(10, -40,  0, -50).maxSpeed(0.8))
        .holdEnd(2.5);

// In steps(Steps s, Robot robot):
s.start("Right of our FLOWER, facing the field", 40, -61, 0)
 .follow("Around", AROUND, 12,
         PathAt.inchesDone(5, Actions.scoreHigh(robot)),
         PathAt.part(2, "Part two", () -> robot.lift.goTo("low")),
         PathAt.near(12, -38, 6, "Near it", robot.intake::in),
         PathAt.inchesLeft(12, "Spin up", robot.launcher::spinUp));

// With the other imports, at the top of the file:
import com.crossbotics.ftchelper.robot.PathAt;

// In steps(Steps s, Robot robot):
s.driveTo("Go 1", -48, -50, 0, 0.6)
 .driveTo("Go 2", -30, -30, 45, 0.5,
          PathAt.fraction(0.62, "Intake on", robot.intake::in));
